INSERT INTO research_companies (name, code, industry, seg, listed, round, cap, valuation, rev, last_funding, data, updated_at) VALUES
('思尔芯', NULL, 'semiconductor', 'eda', false, '战略投资', NULL, NULL, NULL, '2025-12', '{"name":"思尔芯","industry":"semiconductor","seg":"eda","listed":false,"desc":"上海思尔芯技术股份有限公司（S2C，2003 年成立于美国圣何塞、2004 年设上海总部，前身国微思尔芯）是国内首家数字 EDA 供应商，专注集成电路功能验证环节，产品覆盖架构设计、软件仿真、硬件仿真、原型验证、数字调试与 EDA 云。2018 年被国微集团收购，2025 年 12 月获粤港澳大湾区科技创新产业投资基金与华大九天联合战略投资（中湾芯盛持股约 7.78%），成为国产数字 EDA 全流程整合的关键一环。核心产品包括芯神鼎 OD 高性能硬件仿真器（最高逻辑容量 96 亿门、支持硬件仿真与原型验证双模式切换）、芯神瞳 S8-100 第八代原型验证系统（单系统等效约 1 亿门、可拓展至 30 亿 ASIC 门容量），以及 RCF/ICF 自动分割与增量编译工具。已服务全球 600+ 客户，应用于 AI、HPC、CPU、5G、汽车电子等领域，曾助力北京开源芯片研究院「香山·昆明湖」16 核 RISC-V+NOC 验证。公司曾冲刺科创板 IPO 后撤回，2024 年 10 月中金公司因保荐业务未勤勉尽责被证监会处罚。","round":"战略投资","lastFunding":"2025-12","latestFunding":"2025-12 · 战略投资（投资方：大湾区科创基金 / 华大九天）","latestTech":"芯神鼎 OD 高性能硬件仿真器最高逻辑容量达 96 亿门，支持硬件仿真与原型验证双模式切换；RCF/ICF 工具提升超大规模芯片自动分割与增量编译效率","tech":[{"date":"2025-12","title":"获大湾区基金与华大九天联合战略投资，华大九天通过中湾芯盛取得约 7.78% 股份，深化国产数字 EDA 整合"},{"date":"2025-08","title":"芯神鼎 OD 硬件仿真器发布，采用业界最大容量 FPGA，最高逻辑容量 96 亿门"},{"date":"2025","title":"推出 RCF（RTL 自动分割）与 ICF（增量编译）工具，实测支撑开芯院香山昆明湖 16 核 RISC-V SoC 验证"}],"funding":[{"date":"2025-12","round":"战略投资","amount":"1.1 亿元","inv":"大湾区科创基金、华大九天"},{"date":"2022-11","round":"股权融资","inv":"兴橙资本"},{"date":"2020-10","round":"股权融资","inv":"国策投资"},{"date":"2020-09","round":"A 轮","amount":"数亿元人民币","inv":"国投创业、君联资本、张江火炬创投、临港科创投、芯鑫租赁、上海半导体装备材料产业投资基金、鸿泰国微、浦东科创集团"},{"date":"2019-12","round":"战略投资","amount":"约 3.1 亿元","inv":"临创投资"},{"date":"2019-12","round":"天使轮","inv":"临创投资"}],"investorsStructured":[{"name":"大湾区科创基金","role":"lead","round":"战略投资","date":"2025-12","kind":"gov"},{"name":"华大九天","role":"strategic","round":"战略投资","date":"2025-12","kind":"cvc","note":"通过中湾芯盛持有约 7.78%"},{"name":"临创投资","role":"lead","round":"战略投资","date":"2019-12","kind":"gov"},{"name":"国投创业","role":"lead","round":"A 轮","date":"2020-09","kind":"gov"},{"name":"国家集成电路产业投资基金","role":"follow","round":"A 轮","date":"2020-09","kind":"gov"},{"name":"君联资本","role":"follow","round":"A 轮","date":"2020-09","kind":"vc"},{"name":"兴橙资本","role":"lead","round":"股权融资","date":"2022-11","kind":"vc"},{"name":"上海半导体装备材料产业投资基金","role":"follow","round":"A 轮","date":"2020-09","kind":"gov"}],"executives":[{"name":"林俊雄","title":"创始人兼 CEO","role":"management"},{"name":"林铠鹏","title":"法定代表人","role":"management"}],"note":"前身国微思尔芯，2018 年被国微集团（国微控股 2016 年港交所上市）收购并联合承接国家核高基数字全流程 EDA 专项。"}'::jsonb, '2026-10-15T00:33:47.513Z'),
('承芯半导体', NULL, 'semiconductor', 'design', false, 'B+ 轮', NULL, NULL, NULL, '2026-04', '{"name":"承芯半导体","industry":"semiconductor","seg":"design","listed":false,"desc":"常州承芯半导体有限公司（2019-09 成立、2020-04 正式运营，注册资本约 7.35 亿元）由武岳峰资本联合寰宇通讯（GCS）、晶品光电投资设立，董事长潘建岳为武岳峰资本创始合伙人之一，总经理余楚荣拥有 40 余年半导体管理经验。公司是国内少见的射频前端 IDM 模式企业，拥有两座晶圆厂和一座封测厂，具备设计、制造到封测全链条能力。主营业务分两大方向：一是化合物半导体晶圆代工（GaAs/GaN 等二三代半导体制造服务，技术源自美国 GCS 转移，覆盖射频功放 PA、光通信器件），二是高端射频滤波器研发生产（主打 TC-SAW 与 BAW 滤波器，滤波器芯片仅 1.6mm×1.2mm）。已申报 250 多项独立知识产权，实现 5G 通用频段全波段滤波器芯片量产，产品进入小米等手机供应链。公司同时布局三代半导体技术储备，目标是赶超海外射频 IDM。","round":"B+ 轮","lastFunding":"2026-04","latestFunding":"2026-04 · D 轮（投资方：芯智云端 / 苏州芯禾凝瑞）","latestTech":"实现 5G 通用频段全波段 TC-SAW/BAW 滤波器芯片量产；一期产线建成并完成核心代工技术转移，布局 GaN 三代半导体射频制程","tech":[{"date":"2023-03","title":"实现 TC-SAW/BAW 滤波器产品量产出货，一期产线完成建设与技术转移"},{"date":"2022","title":"获评江苏省「潜在独角兽」企业；实现 5G 通用频段全波段滤波器芯片量产"}],"funding":[{"date":"2026-04","round":"D 轮","inv":"芯智云端、苏州芯禾凝瑞"},{"date":"2026-02","round":"B+ 轮","inv":"厚毅资本"},{"date":"2025-07","round":"B 轮","inv":"武进高新投、江苏国经资本"},{"date":"2023-11","round":"A+ 轮","inv":"武岳峰科创、昆桥资本"},{"date":"2022-01","round":"A 轮","amount":"超 10 亿元","inv":"中网投、武岳峰科创领投；中金资本、和诺资本、亦合资本、国联资本、启泰资本、无锡国发、常高新、智和通、中经合鲁信、快克股份、欣翼资本、金泰富资本、小米长江产业基金、华兴新经济基金跟投"},{"date":"2021-09","round":"Pre-A+ 轮","inv":"启泰创投、武岳峰科创、昆桥资本"},{"date":"2020-05","round":"Pre-A 轮","inv":"武进高新投、卓胜微电子"}],"investorsStructured":[{"name":"武岳峰科创","role":"lead","round":"A 轮","date":"2022-01","kind":"vc","note":"创始股东，多轮持续加注"},{"name":"中国互联网投资基金","role":"lead","round":"A 轮","date":"2022-01","kind":"gov"},{"name":"小米长江产业基金","role":"follow","round":"A 轮","date":"2022-01","kind":"cvc"},{"name":"中金资本","role":"follow","round":"A 轮","date":"2022-01","kind":"vc"},{"name":"华兴新经济基金","role":"follow","round":"A 轮","date":"2022-01","kind":"vc"},{"name":"启泰创投","role":"lead","round":"Pre-A+ 轮","date":"2021-09","kind":"vc"},{"name":"昆桥资本","role":"follow","round":"A+ 轮","date":"2023-11","kind":"vc"},{"name":"武进高新投","role":"lead","round":"B 轮","date":"2025-07","kind":"gov"},{"name":"卓胜微电子","role":"strategic","round":"Pre-A 轮","date":"2020-05","kind":"cvc"},{"name":"厚毅资本","role":"lead","round":"B+ 轮","date":"2026-02","kind":"vc"}],"executives":[{"name":"潘建岳","title":"董事长","role":"board","bio":"武岳峰资本创始合伙人，曾任美国新思科技中国区总裁"},{"name":"余楚荣","title":"总经理","role":"management","bio":"40 余年半导体资深管理经验"}],"note":"公司曾用名常州新晶宇光电有限公司，由环宇-KY 与晶品光电合资设立，旨在建置 6 吋化合物半导体晶圆厂。"}'::jsonb, '2026-10-15T00:33:47.513Z'),
('泰矽微', NULL, 'semiconductor', 'design', false, 'B 轮', NULL, NULL, NULL, '2025-12', '{"name":"泰矽微","industry":"semiconductor","seg":"design","listed":false,"desc":"上海泰矽微电子有限公司（2019-09 成立，创始人兼董事长熊海峰）是清华长三角研究院重点合作与扶持的高性能专用 SoC 芯片企业，专注将高可靠性低功耗 MCU 与射频、信号链、电源管理等模拟/混合信号 IP 融合，打造覆盖消费、工业、医疗、汽车的平台型 MCU 产品线。产品包括 AFE MCU（血氧仪、燃气报警、工业/气体传感）、新一代人机交互 MCU（消费与车规双版本，已通过 AEC-Q100，进入多家整车厂与 Tier1）、中高端 TWS 充电仓 PMIC MCU（单 Die 集成 10 颗以上 IC 功能）、车规级智能触控 SoC（TCAExx-QDA2 已量产）及集成式微马达驱动芯片（累计出货千万颗级）。车规触控芯片为国内龙头，产品已进入大众、红旗、吉利、奇瑞、通用、零跑、领克、极氪、北汽、福特、东风、广汽、一汽、蔚来、长安等主机厂。公司与歌尔股份达成长期合作，与哈工大（深圳）共建联合实验室，并通过莱茵 TÜV ASIL D 功能安全流程认证。","round":"B 轮","lastFunding":"2025-12","latestFunding":"2025-12 · B 轮（投资方：光谷产业投资 / 昌达母基金 / 芯智能基金）","latestTech":"车规级智能触控 SoC TCAExx-QDA2 量产；业内首款面向高端蓝牙耳机充电仓单芯片方案 TCPT22；集成式微马达驱动芯片累计出货达千万颗量级","tech":[{"date":"2022-03","title":"量产车规级智能触控 SoC 解决方案 TCAExx-QDA2，通过 AEC-Q100 Grade 1 认证"},{"date":"2022-06","title":"与莱茵 TÜV 签约启动 ASIL D 功能安全流程认证；业内首款双模人机交互芯片 TCAE31 通过车规 AEC-Q100 认证"},{"date":"2021-09","title":"量产系列化「MCU+」产品——TWS 耳机三合一人机交互芯片与高性能信号链 SoC"}],"funding":[{"date":"2025-12","round":"B 轮","amount":"近 1 亿元","inv":"光谷产业投资、昌达母基金、芯智能基金"},{"date":"2025-02","round":"战略融资","amount":"数千万元","inv":"日盈电子、红猫创投"},{"date":"2024-09","round":"战略融资","amount":"数千万元","inv":"浙江联益控股"},{"date":"2024-04","round":"战略融资","amount":"数千万元","inv":"博奥集团"},{"date":"2023-09","round":"战略融资","amount":"数千万元","inv":"星宇股份"},{"date":"2022-01","round":"A+ 轮","amount":"近 3 亿元","inv":"武岳峰科创领投；冯源基金、芯域行、海松资本跟投"},{"date":"2021-05","round":"A 轮","amount":"数千万元","inv":"海松资本、祥御资本、襄创创业、霍格沃茨投资"},{"date":"2020-12","round":"Pre-A 轮","amount":"数千万元","inv":"张江科投、襄创创业"},{"date":"2019-12","round":"天使轮","amount":"数千万元","inv":"普华资本"},{"date":"2019-09","round":"种子轮","inv":"勤桦投资"}],"investorsStructured":[{"name":"武岳峰科创","role":"lead","round":"A+ 轮","date":"2022-01","kind":"vc"},{"name":"海松资本","role":"lead","round":"A 轮","date":"2021-05","kind":"vc","note":"A+ 轮继续追加"},{"name":"冯源基金","role":"follow","round":"A+ 轮","date":"2022-01","kind":"vc"},{"name":"普华资本","role":"lead","round":"天使轮","date":"2019-12","kind":"vc"},{"name":"张江科投","role":"lead","round":"Pre-A 轮","date":"2020-12","kind":"gov"},{"name":"光谷产业投资","role":"lead","round":"B 轮","date":"2025-12","kind":"gov"},{"name":"星宇股份","role":"strategic","round":"战略融资","date":"2023-09","kind":"cvc"},{"name":"博奥集团","role":"strategic","round":"战略融资","date":"2024-04","kind":"cvc"}],"executives":[{"name":"熊海峰","title":"创始人、董事长兼 CEO","role":"management","bio":"创始团队来自 Atmel、TI、Marvell、海思等国际芯片厂商，平均 15 年工作经验"}],"note":"愿景为覆盖全系列高端 MCU 的平台型企业，重点打造高可靠工规与车规产品线。"}'::jsonb, '2026-10-15T00:33:47.513Z'),
('原粒半导体', NULL, 'semiconductor', 'design', false, 'A 轮', NULL, 51.55, NULL, '2026-07', '{"name":"原粒半导体","industry":"semiconductor","seg":"design","listed":false,"desc":"北京原粒半导体有限公司（2023-04 成立，创始人兼 CEO 方绍峡博士曾任 AMD 芯片研发总监、Xilinx AI 处理器研发总监，拥有 50 余项中美 AI 芯片发明专利）是国内 AI Chiplet（芯粒）供应商，聚焦「端侧生产力 AI 芯片」，用 Chiplet 积木式架构把数据中心级算力下沉到桌面与边缘设备，面向长期运行、持续执行任务的生产力 Agent 场景（企业办公、行业 Agent、工业智能、本地大模型部署）。公司构建 CalcuMex、CalcuGrid、CalcuKit 三大技术体系：CalcuMex 针对大模型推理「内存墙」构建以片上 SRAM 为核心的混合自适应数据流架构；CalcuGrid 为面向 AI 芯粒的弹性互联与异构集成架构；CalcuKit 为硬件感知编译与智能调度系统。核心团队来自 AMD、赛灵思等国际半导体巨头，具备多代 AI 芯片研发经验。2026-05 首款端侧生产力 AI 芯片 CCS-1 系列流片点亮，原生支持主流 Agent 生态，可在本地运行千亿参数大模型。2026 年 4 月与 7 月三个月内累计融资超 12 亿元，A 轮投后估值约 51.55 亿元。","valuation":51.55,"round":"A 轮","lastFunding":"2026-07","latestFunding":"2026-07 · A 轮（超 7 亿元，投资方：九安医疗 / 汤臣倍健 / 绿茵生态 / 北洋海棠基金 / 仁爱基金 / IDG 资本 / 武岳峰科创 / 英诺 / 一维创投）","latestTech":"首款端侧生产力 AI 芯片 CCS-1 系列 2026-05 流片点亮，原生支持主流 Agent 生态，可在本地运行千亿参数大模型；CalcuMex/CalcuGrid/CalcuKit 三位一体技术体系","tech":[{"date":"2026-07","title":"完成超 7 亿元 A 轮融资，三个月累计融资超 12 亿元，投后估值约 51.55 亿元"},{"date":"2026-05","title":"首款端侧生产力 AI 芯片 CCS-1 系列成功流片并点亮"},{"date":"2026-04","title":"完成超 5 亿元 Pre-A 轮融资，IDG 资本领投"}],"funding":[{"date":"2026-07","round":"A 轮","amount":"超 7 亿元","inv":"九安医疗、汤臣倍健、绿茵生态、北洋海棠基金、仁爱基金联合投资；IDG 资本、武岳峰科创、英诺、一维创投持续加注"},{"date":"2026-04","round":"Pre-A 轮","amount":"超 5 亿元","inv":"IDG 资本领投；武岳峰科创、国新基金、尚势资本、红鸟启航基金、领屹投资、首发展创投、香港木棉花基金、英诺、中科创星、一维创投、水木清华校友种子基金跟投"},{"date":"2023-06","round":"种子轮","amount":"数千万元","inv":"英诺、中科创星等"}],"investorsStructured":[{"name":"IDG 资本","role":"lead","round":"Pre-A 轮","date":"2026-04","kind":"vc","note":"独家领投，A 轮继续加注"},{"name":"武岳峰科创","role":"follow","round":"Pre-A 轮","date":"2026-04","kind":"vc","note":"老股东持续加注"},{"name":"国新基金","role":"follow","round":"Pre-A 轮","date":"2026-04","kind":"gov"},{"name":"九安医疗","role":"lead","round":"A 轮","date":"2026-07","kind":"cvc"},{"name":"汤臣倍健","role":"follow","round":"A 轮","date":"2026-07","kind":"cvc","note":"出资 5000 万元持股 0.97%，财务性投资"},{"name":"绿茵生态","role":"follow","round":"A 轮","date":"2026-07","kind":"cvc"},{"name":"北洋海棠基金","role":"follow","round":"A 轮","date":"2026-07","kind":"vc"},{"name":"中科创星","role":"follow","round":"种子轮","date":"2023-06","kind":"vc"}],"executives":[{"name":"方绍峡","title":"创始人兼 CEO","role":"management","bio":"清华校友，曾任 AMD 芯片研发总监、Xilinx（赛灵思）AI 处理器研发总监，拥有 50 余项中美 AI 芯片发明专利"}],"note":"产品定位「端侧生产力 AI 芯片」，原生支持 Agent 生态，相当于「Mac Mini + 无限免费的本地 Tokens」。"}'::jsonb, '2026-10-15T00:33:47.513Z'),
('芯砺智能', NULL, 'semiconductor', 'design', false, 'Pre-A++ 轮', NULL, NULL, NULL, '2023-09', '{"name":"芯砺智能","industry":"semiconductor","seg":"design","listed":false,"desc":"芯砺智能科技（上海）有限公司（2021-11 成立，创始人兼 CEO 张宏宇为清华大学电子工程系 90 级，拥有 25 年国际化 SoC 研发及管理经验）是全球首家利用芯粒（Chiplet）技术研发车载大算力芯片的企业，聚焦智能汽车 E/E 架构走向跨域融合、中央计算平台的趋势，提供兼具大算力、高性价比、可定制的智能汽车算力平台芯片。公司拥有独创的 Chiplet 互连技术，可提供高带宽、低延迟的片间（die-to-die）互连总线，结合创新的嵌入式高性能计算平台（eHPC）芯片架构，利用相对成熟的半导体制造与封装技术突破对先进工艺的依赖。张宏宇此前曾在掌微科技（Centrality）主导车载导航娱乐 SoC（2007 年全球车规 SoC 市占率超 70%，被 SiRF 以近 3 亿美元收购），并在赛灵思负责 16nm UltraScale+ 与 7nm Versal 两代高性能计算平台芯片（通过车规与功能安全认证）。公司累计融资 4 轮，2023-06 Pre-A+ 轮超 3 亿元。","round":"Pre-A++ 轮","lastFunding":"2023-09","latestFunding":"2023-09 · Pre-A++ 轮（投资方：睿悦控股集团 / 经纬创投）","latestTech":"独创 Chiplet 片间互连总线（高带宽低延迟 die-to-die）+ eHPC 嵌入式高性能计算平台架构，以成熟制程与先进封装突破先进工艺依赖","tech":[{"date":"2023-06","title":"完成超 3 亿元 Pre-A+ 轮融资，武岳峰科创、经纬创投、GIC、扬子江基金等参与"},{"date":"2022-08","title":"半年内获近 3 亿元天使轮及产业轮融资，成为全球首家以 Chiplet 技术研发车载大算力芯片的企业"}],"funding":[{"date":"2023-09","round":"Pre-A++ 轮","inv":"睿悦控股集团、经纬创投"},{"date":"2023-06","round":"Pre-A+ 轮","amount":"超 3 亿元","inv":"武岳峰科创、经纬创投、GIC 新加坡政府投资公司、扬子江基金、海望资本、常州政府引导基金、中电基金、谷雨嘉禾、启泰资本、江苏国经资本"},{"date":"2022-08","round":"Pre-A 轮","inv":"某产业投资机构"},{"date":"2021-12","round":"天使轮","inv":"经纬创投、武岳峰科创"}],"investorsStructured":[{"name":"武岳峰科创","role":"lead","round":"Pre-A+ 轮","date":"2023-06","kind":"vc"},{"name":"经纬创投","role":"lead","round":"天使轮","date":"2021-12","kind":"vc","note":"多轮持续加注"},{"name":"GIC 新加坡政府投资公司","role":"follow","round":"Pre-A+ 轮","date":"2023-06","kind":"gov"},{"name":"海望资本","role":"follow","round":"Pre-A+ 轮","date":"2023-06","kind":"gov"},{"name":"常州政府引导基金","role":"follow","round":"Pre-A+ 轮","date":"2023-06","kind":"gov"},{"name":"中电基金","role":"follow","round":"Pre-A+ 轮","date":"2023-06","kind":"gov"},{"name":"睿悦控股集团","role":"lead","round":"Pre-A++ 轮","date":"2023-09","kind":"vc"}],"executives":[{"name":"张宏宇","title":"创始人兼 CEO","role":"management","bio":"清华大学电子工程系 90 级，25 年国际化企业 SoC 产品研发及管理经验；曾创办掌微科技（车载导航娱乐 SoC 全球市占率超 70%），后于赛灵思负责 16nm UltraScale+ 与 7nm Versal 芯片研发"}],"note":"云岫资本担任独家财务顾问；创始人主导了当前国际上最大规模 7nm 车规芯片的研发和量产。"}'::jsonb, '2026-10-15T00:33:47.513Z'),
('清微智能', NULL, 'semiconductor', 'design', false, 'C 轮', NULL, NULL, NULL, '2025-12', '{"name":"清微智能","industry":"semiconductor","seg":"design","listed":false,"desc":"北京清微智能科技股份有限公司（2018-07 成立，创始人、董事长兼 CEO 王博，联合创始人兼首席科学家尹首一为清华大学集成电路学院院长、IEEE Fellow）脱胎于清华大学可重构计算方向近二十年技术积累，是与摩尔线程、昆仑芯、寒武纪并列的北京 AI 芯片「四大金刚」之一，也是国内研发「非 GPU」新型架构 AI 芯片的代表企业。核心技术为「软件定义硬件」的 RPU（可重构处理单元）架构，通过算子动态重构在 GPU 通用性与 ASIC 高能效之间取得平衡，被称为「通用型 TPU」或「高阶 TPU」，整体成本降低 50%、能效比提升 3 倍。已量产 TX8 系列云端算力芯片（TX81 为国内首颗可重构 AI 训练/推理芯片，支持万亿参数大模型）与 TX5 系列边缘端芯片（TX510、TX210），累计芯片出货量超 3000 万颗，算力卡订单累计超 3 万张，在全国十余座千卡规模智算中心规模化落地。2025 年完成超 20 亿元 C 轮融资并启动上市筹备，2026-06 提交 IPO 辅导完成报告（拟申报创业板）。","round":"C 轮","lastFunding":"2025-12","latestFunding":"2025-12 · C 轮（超 20 亿元，投资方：京能集团领投 / 北创投 / 建投投资 / 武岳峰科创 / 成都科创投等）","latestTech":"可重构 3.0 架构；TX8 系列云端算力芯片（TX81 支持万亿参数大模型）、TX5 系列边缘芯片；自研 RAISA 软件栈兼容 CUDA 并融入 FlagOS 国产生态","tech":[{"date":"2025-12","title":"完成超 20 亿元 C 轮融资，已启动上市筹备工作，目标打造国内「非 GPU」新型架构芯片领域首个上市标杆"},{"date":"2025","title":"与北京智源人工智能研究院共建联合实验室，成为 FlagOS 卓越适配单位；成立北京市可重构算力软硬件协同技术创新中心"},{"date":"2024","title":"TX81 可重构 AI 芯片规模化落地，累计算力卡订单超 2 万张"}],"funding":[{"date":"2025-12","round":"C 轮","amount":"超 20 亿元","inv":"京能集团领投；北创投、建投投资、武岳峰科创、成都科创投、华泰紫金、智路资本、中南泊富、凯联资本、图灵资产、硬核坚果资本、拓锋投资、米聚资本、允泰资本、和而泰、中科元创跟投；京国瑞、中关村科学城公司、商汤国香资本、闻名投资、卓源亚洲、源余投资、考拉基金追投"},{"date":"2023","round":"B 轮","inv":"国家大基金二期、蚂蚁集团、百度、商汤国香、"},{"date":"2018","round":"天使轮","inv":"清华大学（知识产权入股）、松禾资本等"}],"investorsStructured":[{"name":"京能集团","role":"lead","round":"C 轮","date":"2025-12","kind":"gov"},{"name":"武岳峰科创","role":"follow","round":"C 轮","date":"2025-12","kind":"vc"},{"name":"北创投","role":"follow","round":"C 轮","date":"2025-12","kind":"gov"},{"name":"建投投资","role":"follow","round":"C 轮","date":"2025-12","kind":"gov"},{"name":"国家集成电路产业投资基金二期","role":"follow","round":"B 轮","date":"2023","kind":"gov"},{"name":"蚂蚁集团","role":"follow","round":"B 轮","date":"2023","kind":"cvc"},{"name":"百度","role":"follow","round":"B 轮","date":"2023","kind":"cvc"},{"name":"商汤国香资本","role":"follow","round":"C 轮","date":"2025-12","kind":"cvc","note":"B 轮已投，C 轮追投"},{"name":"中关村科学城公司","role":"follow","round":"C 轮","date":"2025-12","kind":"gov"},{"name":"清华大学","role":"strategic","round":"天使轮","date":"2018","kind":"other","note":"知识产权入股"}],"executives":[{"name":"王博","title":"创始人、董事长兼 CEO","role":"management","bio":"1978 年生，北京邮电大学计算机通信专业硕士；曾任汉柏科技 CTO，2025 年获「中国 IC 设计业年度企业家」称号"},{"name":"尹首一","title":"联合创始人兼首席科学家","role":"board","bio":"清华大学集成电路学院院长、长聘教授、IEEE Fellow、国家杰出青年科学基金获得者"},{"name":"欧阳鹏","title":"联合创始人兼 CTO","role":"management","bio":"清华大学博士，集成电路正高级专家，主持 10 余款新型智能计算芯片核心架构设计"},{"name":"李秀冬","title":"联合创始人兼产品工程 VP","role":"management","bio":"曾就职于清华大学微电子学研究所及英伟达"}],"note":"股权结构：法定代表人王博，赋华同创持股 13.77% 为控股股东；王博通过直接与间接合计拥有约 24.44% 表决权。"}'::jsonb, '2026-10-15T00:33:47.513Z'),
('首传微', NULL, 'semiconductor', 'design', false, 'B++ 轮', NULL, NULL, NULL, '2026-06', '{"name":"首传微","industry":"semiconductor","seg":"design","listed":false,"desc":"首传微电子（常州）有限公司（2021-03 成立于苏州，2024-04 更名并迁入常州武进高新区）是国内极少数聚焦 MIPI A-PHY 国际标准 + HSMT 中国自主标准双协议车载 SerDes（串并转换）PHY 芯片的 Fabless 芯片设计企业，聚焦车载 IVN（车载内部网络）超高速通信芯片赛道，打破 ADI、TI、美信等海外巨头的私有协议垄断。核心团队来自 TI、展讯、Marvell、高通等半导体企业，平均行业经验超 20 年。创始人任刚熟悉全球 MIPI 联盟标准制定规则与国内 HSMT 车载传输标准起草生态；联合创始人兼 CEO 张晨光主导 VL77XX 全系产品主机厂定点与吉利领克车型量产落地。核心产品为 VL77XX 量产系列 SerDes 芯片，分为 A-PHY 单协议、A-PHY+HSMT 双模、HSMT 高速 PAM4 三大产品线，配套 IEEE802.3 标准车载以太网 PHY 芯片与 ISP+SerDes 集成方案。2022 年完成国内首款 A-PHY 全功能串行器与解串器对片流片验证并获 SGS ISO26262 ASIL-D 流程认证；2024-12 2G/4G 产品量产；2025-04 发布全球首款双协议 SerDes 芯片组；2025-07 HSMT 12.8Gbps PAM4 高速 SerDes 量产。","round":"B++ 轮","lastFunding":"2026-06","latestFunding":"2026-06 · B++ 轮（数千万人民币，投资方：常州政府投资基金 / 苏州敦钧 / 常金控旗下诺汇基金）","latestTech":"全球首款同时兼容国际 A-PHY 与国产 HSMT 两大公有标准的商用 SerDes 芯片（2025-04 上海车展发布量产）；HSMT 12.8Gbps PAM4 高速 SerDes 芯片 2025-07 落地量产","tech":[{"date":"2025-07","title":"VL7722(F) 解串器通过 SGS AEC-Q100 Grade 2 车规认证；HSMT 12.8Gbps PAM4 高速 SerDes 芯片量产；SerDes 芯片在吉利领克 06 车型首发量产"},{"date":"2025-04","title":"上海车展发布支持 MIPI A-PHY 与 HSMT 双协议标准的车载 SerDes 芯片组，为全球首款双协议商用 SerDes"},{"date":"2024-12","title":"2G/4G 产品实现量产；工程样片通过电磁兼容测试，全功能 8Gb/s PAM4 图传成功"},{"date":"2022","title":"完成国内首款 A-PHY 全功能串行器与解串器对片流片验证，获 SGS ISO26262:2018 ASIL-D 流程认证"}],"funding":[{"date":"2026-06","round":"B++ 轮","amount":"数千万元","inv":"常州政府投资基金、苏州敦钧、常金控旗下诺汇基金"},{"date":"2024-06","round":"B+ 轮","inv":"汇智资本、江苏国经资本、武进高新投、常州蒲公英创投"},{"date":"2024-01","round":"B 轮","amount":"超 1 亿元","inv":"武岳峰科创领投；中芯熙诚、清研资本跟投"},{"date":"2022-02","round":"A 轮","inv":"瀚联产业基金（江阴瀚联智芯）、联想之星"},{"date":"2021-06","round":"天使+ 轮","inv":"沃赋创投"},{"date":"2021-04","round":"天使轮","inv":"湖杉资本（湖杉原芯半导体天使基金）"}],"investorsStructured":[{"name":"武岳峰科创","role":"lead","round":"B 轮","date":"2024-01","kind":"vc"},{"name":"中芯熙诚","role":"follow","round":"B 轮","date":"2024-01","kind":"cvc"},{"name":"清研资本","role":"follow","round":"B 轮","date":"2024-01","kind":"vc"},{"name":"湖杉资本","role":"lead","round":"天使轮","date":"2021-04","kind":"vc"},{"name":"瀚联产业基金","role":"lead","round":"A 轮","date":"2022-02","kind":"vc"},{"name":"联想之星","role":"follow","round":"A 轮","date":"2022-02","kind":"vc"},{"name":"武进高新投","role":"lead","round":"B+ 轮","date":"2024-06","kind":"gov"},{"name":"常州政府投资基金","role":"lead","round":"B++ 轮","date":"2026-06","kind":"gov"}],"executives":[{"name":"任刚","title":"创始人、董事长兼总经理","role":"management","bio":"曾任职国际头部半导体大厂，熟悉全球 MIPI 联盟标准制定规则与国内 HSMT 车载传输标准起草生态；持股 12.63%"},{"name":"张晨光","title":"联合创始人兼 CEO","role":"management","bio":"曾任职海外知名模拟半导体企业与国内头部 IC 设计公司，主导 VL77XX 全系产品主机厂定点与吉利领克车型量产"},{"name":"陈继凯","title":"董事","role":"board"}],"note":"已与富瀚微、Valens、芯擎科技、爱芯元智等生态伙伴推出联合解决方案；与中国汽研签署合作协议构建 SerDes 全链路测评体系。"}'::jsonb, '2026-10-15T00:33:47.513Z'),
('巨风半导体', NULL, 'semiconductor', 'design', false, 'C 轮', NULL, NULL, NULL, '2025-11', '{"name":"巨风半导体","industry":"semiconductor","seg":"design","listed":false,"desc":"广东巨风半导体有限公司（2019-08 成立，曾用名巨风芯科技（深圳）有限公司，法定代表人 FANG MIN JENNIFER 方敏）由原国际整流器公司（IR，后并入英飞凌）美国研发中心研发总监归国创立，专注高端功率半导体芯片的研发与制造，产品涵盖驱动 IC、电源管理芯片（PMIC）、智能功率模块（IPM）、功率器件及功率模块。公司是国内少数实现全系列栅极驱动芯片（Driver IC）与绝缘栅双极型晶体管（IGBT）自主研发的功率半导体企业，拥有 80+ 国内外专利，产品性能达国际先进水平，广泛应用于白色家电、工业变频、新能源汽车、光伏储能等领域，已进入美的、格力、汇川技术、广汽等多家行业龙头核心供应链。股东阵容包括深创投、武岳峰、中芯聚源、元禾璞华、工控资本、广州产投、汇川技术、广汽资本、尚颀资本等，形成「技术+产业+资本」深度融合生态。公司总部 2025 年 10 月由广州黄埔区迁至深圳南山区。","round":"C 轮","lastFunding":"2025-11","latestFunding":"2025-11 · C 轮（数亿元，投资方：深创投 / 深重投 / 南山战新投 / 泽奕资本）","latestTech":"国内唯一实现全系列栅极驱动芯片（Driver IC）与 IGBT 自主研发的功率半导体企业；产品性能达国际先进水平，进入美的、格力、汇川、广汽核心供应链","tech":[{"date":"2025-11","title":"完成数亿元 C 轮融资，用于高端功率半导体研发迭代、产能提升及市场拓展"},{"date":"2022-03","title":"完成 B 轮融资，武岳峰科创、深创投、汇川产投等参与"}],"funding":[{"date":"2025-11","round":"C 轮","amount":"数亿元","inv":"深创投、深重投、南山战新投、泽奕资本"},{"date":"2023-07","round":"B+ 轮","inv":"京铭资本、工控资本、广视基金、广汽资本、万方资本、智光电气、广州产投集团、海创基金、国铸资本"},{"date":"2022-08","round":"战略融资","inv":"尚颀资本、广汽资本"},{"date":"2022-03","round":"B 轮","inv":"武岳峰科创、广州开发区产业基金、汇川产投、深创投"},{"date":"2020-09","round":"A 轮","inv":"中芯聚源、元禾璞华"}],"investorsStructured":[{"name":"武岳峰科创","role":"follow","round":"B 轮","date":"2022-03","kind":"vc"},{"name":"深创投","role":"lead","round":"C 轮","date":"2025-11","kind":"gov","note":"B 轮已投"},{"name":"中芯聚源","role":"lead","round":"A 轮","date":"2020-09","kind":"cvc"},{"name":"元禾璞华","role":"follow","round":"A 轮","date":"2020-09","kind":"gov"},{"name":"汇川产投","role":"follow","round":"B 轮","date":"2022-03","kind":"cvc"},{"name":"广汽资本","role":"follow","round":"战略融资","date":"2022-08","kind":"cvc"},{"name":"尚颀资本","role":"follow","round":"战略融资","date":"2022-08","kind":"cvc"},{"name":"广州产投集团","role":"follow","round":"B+ 轮","date":"2023-07","kind":"gov"},{"name":"南山战新投","role":"follow","round":"C 轮","date":"2025-11","kind":"gov"}],"executives":[{"name":"FANG MIN JENNIFER","title":"创始人、法定代表人","role":"management","bio":"原国际整流器公司（IR，后并入英飞凌）美国研发中心研发总监，归国创立巨风半导体"}],"note":"广东省省级「专精特新」、潜在独角兽企业；2025 年 10 月总部由广州黄埔区迁至深圳南山区。"}'::jsonb, '2026-10-15T00:33:47.513Z'),
('忱芯科技', NULL, 'semiconductor', 'equipment', false, 'C+ 轮', NULL, NULL, NULL, '2025-12', '{"name":"忱芯科技","industry":"semiconductor","seg":"equipment","listed":false,"desc":"忱芯科技（上海）有限公司（UniSiC，2020-01 成立，法定代表人毛赛君博士）是国内功率半导体自动化测试系统解决方案创新领导者，核心团队来自 GE 中央研究院，自主研发多项业内首台套碳化硅核心功率部件产品。产品可覆盖 SiC、GaN 及 Si 基功率半导体器件各测试环节，包括晶圆级动态 WLBI 测试系统、芯片级 KGD 测试系统、双极退化测试系统、动态/静态测试系统（Edison/Maxwell 系列）、动态可靠性测试系统（Steinmetz 系列）、晶圆级测试系统（Acheson 系列）等，全面覆盖晶圆级、芯片级、单管/模块级和系统级测试。同时深耕高端医疗影像设备核心子部件——双能瞬切高频高压发生器赛道，实现 500kHz 开关频率、100kW 功率、168kV 电压、碳化硅功率电路 <50μs kV 瞬态切换，无效剂量降低达 90%。2024-09 获国家级专精特新「小巨人」，2024-11 德国办公室开业，2025-12 入选上海市科技小巨人企业。","round":"C+ 轮","lastFunding":"2025-12","latestFunding":"2025-12 · C+ 轮（亿级人民币，投资方：长江创新投资 / 金浦投资）","latestTech":"SiC 功率半导体测试系统全谱系（晶圆级动态 WLBI、芯片级 KGD、双极退化、动态可靠性 Steinmetz 系列等）；高端医疗影像双能瞬切高频高压发生器（500kHz、100kW、168kV）","tech":[{"date":"2025-12","title":"完成亿元级 C+ 轮战略融资；入选 2025 年度上海市科技小巨人企业"},{"date":"2024-12","title":"完成 2 亿元 B 轮融资；德国办公室正式开业"},{"date":"2023-10","title":"完成亿元 A+ 轮融资（火山石投资、华润资本、武岳峰科创）"},{"date":"2022-12","title":"完成 A 轮亿元级融资，武岳峰半导体产业基金独家领投"}],"funding":[{"date":"2025-12","round":"C+ 轮","amount":"1 亿元","inv":"长江创新投资、金浦投资"},{"date":"2025-07","round":"C 轮","inv":"工银资本"},{"date":"2024-12","round":"B 轮","amount":"2 亿元","inv":"国投创业、火山石投资、阳光融汇资本、苏州国发创投"},{"date":"2023-10","round":"A+ 轮","amount":"1 亿元","inv":"火山石投资、华润资本（润科基金）、武岳峰科创"},{"date":"2022-12","round":"A 轮","amount":"1 亿元","inv":"武岳峰半导体产业基金独家领投；东方嘉富跟投"},{"date":"2022-03","round":"Pre-A 轮","amount":"近 1 亿元","inv":"东方嘉富、原子创投"},{"date":"2020-08","round":"天使轮","amount":"数千万元","inv":"原子创投"}],"investorsStructured":[{"name":"武岳峰科创","role":"lead","round":"A 轮","date":"2022-12","kind":"vc","note":"通过武岳峰半导体产业基金独家领投，A+ 轮继续加注，为碳化硅领域重点布局"},{"name":"火山石投资","role":"lead","round":"A+ 轮","date":"2023-10","kind":"vc"},{"name":"华润资本（润科基金）","role":"follow","round":"A+ 轮","date":"2023-10","kind":"cvc"},{"name":"国投创业","role":"lead","round":"B 轮","date":"2024-12","kind":"gov"},{"name":"东方嘉富","role":"lead","round":"Pre-A 轮","date":"2022-03","kind":"vc"},{"name":"原子创投","role":"lead","round":"天使轮","date":"2020-08","kind":"vc"},{"name":"长江创新投资","role":"lead","round":"C+ 轮","date":"2025-12","kind":"vc"},{"name":"金浦投资","role":"follow","round":"C+ 轮","date":"2025-12","kind":"vc"}],"executives":[{"name":"毛赛君","title":"创始人兼 CEO","role":"management","bio":"博士，核心团队来自 GE 中央研究院，持股 30.04%"}],"note":"2021-11 获国家高新技术企业认定；2022-03 累计融资超 1 亿元。SiC ATE 已开启海外装机。"}'::jsonb, '2026-10-15T00:33:47.513Z'),
('果纳半导体', NULL, 'semiconductor', 'equipment', false, 'C 轮', NULL, 21.62, NULL, '2026-01', '{"name":"果纳半导体","industry":"semiconductor","seg":"equipment","listed":false,"desc":"上海果纳半导体技术股份有限公司（2020-03 成立，创始人、董事长兼 CEO 叶莹，在半导体行业浸润超 20 年）专注半导体制造环节的智能传输与自动化物料搬运设备，产品覆盖前道晶圆传输、自动物料系统（AMHS）到后道封装自动化设备，是国内唯一实现规模化交付全流程智能半导体传输系统的本土企业。主要产品为 EFEM（半导体设备前端模块）和 Sorter（晶圆分拣设备）及零部件。创始人叶莹曾任职中芯国际、Chartered Semiconductor、灿芯科技、芯恩集成、上海精测等，2020 年 55 岁创业，锚定 12 英寸晶圆厂核心晶圆传输设备赛道。据弗若斯特沙利文，2025 年按收入计，公司在中国智能半导体传输系统市场与晶圆传输设备市场均位列国内第二（份额分别为 2.7% 及 6.3%），在 12 英寸晶圆制造领域晶圆传输设备市场中国企业中排第一（份额 7.8%）。2023-2025 年营收分别为 1.33 亿、3.09 亿、5.22 亿元，两年复合增长率约 98.1%，2025 年经调整净利润 1382 万元首次转正。2023-12 收购马来西亚 Waftech 70% 股份补齐后道业务短板；2026-05 递表港交所主板（保荐人国泰海通），C 轮投后估值约 21.62 亿元。","valuation":21.62,"round":"C 轮","lastFunding":"2026-01","latestFunding":"2026-01 · C 轮（1.7 亿元）","latestTech":"国内唯一规模化交付全流程智能半导体传输系统；EFEM 与 Sorter 产品出货至国内两大龙头半导体设备供应商；累计获发明专利超 130 项","tech":[{"date":"2026-05","title":"递表港交所主板，独家保荐人国泰海通；募资用于 AMHS 软件控制系统与硬件执行单元研发"},{"date":"2026-01","title":"完成 1.7 亿元 C 轮融资，投后估值约 21.62 亿元"},{"date":"2023-12","title":"收购马来西亚 Waftech 70% 股份，产品线拓展至半导体封装自动化设备后端"}],"funding":[{"date":"2026-01","round":"C 轮","amount":"1.7 亿元","inv":"苏州纽尔利、广州鼎峰新能等"},{"date":"2023-05","round":"B+ 轮","inv":"中芯聚源、同创普润资本、江丰电子、西上海"},{"date":"2022-07","round":"B 轮","inv":"金浦投资、武岳峰科创、临芯投资、上海旺鸿、齐芯资本、弘卓资本、至纯科技"},{"date":"2021-09","round":"A+ 轮","amount":"数千万元","inv":"中鑫资本、兆恒水电、通富微电（华达微电）"},{"date":"2021-07","round":"股权融资","inv":"中鑫创新、兆恒水电、众行资本、风投侠基金"},{"date":"2021-01","round":"A 轮","inv":"众行资本、FutureX 天际资本"},{"date":"2020-06","round":"天使轮","amount":"1100 万元","inv":"李斌、陈敏、王美娟"}],"investorsStructured":[{"name":"武岳峰科创","role":"follow","round":"B 轮","date":"2022-07","kind":"vc","note":"现由鼎峰科创（原武岳峰资本）持股 2.91%"},{"name":"金浦投资","role":"lead","round":"B 轮","date":"2022-07","kind":"vc"},{"name":"中芯聚源","role":"lead","round":"B+ 轮","date":"2023-05","kind":"cvc"},{"name":"临芯投资","role":"follow","round":"B 轮","date":"2022-07","kind":"vc"},{"name":"至纯科技","role":"strategic","round":"B 轮","date":"2022-07","kind":"cvc"},{"name":"江丰电子","role":"strategic","round":"B+ 轮","date":"2023-05","kind":"cvc"},{"name":"通富微电（华达微电）","role":"strategic","round":"A+ 轮","date":"2021-09","kind":"cvc"},{"name":"苏州纽尔利","role":"lead","round":"C 轮","date":"2026-01","kind":"vc"}],"executives":[{"name":"叶莹","title":"创始人、董事长兼 CEO","role":"management","bio":"逾 20 年半导体行业经验，曾任职中芯国际人力资源经理、Chartered Semiconductor、灿芯科技、芯恩集成、上海精测副总经理；通过三个持股平台合计控制 54.74% 股份"},{"name":"Stephen Jin","title":"非执行董事","role":"board","bio":"叶莹之子，27 岁，现于美国康奈尔大学读研"}],"note":"国内半导体传输设备市场 2021-2025 年规模从 70 亿元增至 146 亿元（CAGR 20.2%），预计 2030 年达 272 亿元。"}'::jsonb, '2026-10-15T00:33:47.513Z'),
('天锐星通', NULL, 'semiconductor', 'equipment', false, 'F 轮', NULL, NULL, NULL, '2025-06', '{"name":"天锐星通","industry":"semiconductor","seg":"equipment","listed":false,"desc":"成都天锐星通科技股份有限公司（2013-07 成立，法定代表人张成军）是专注于微波、毫米波有源相控阵芯片和天线的国家高新技术企业，具备芯片-模块-天线-整机方案-测试全链条自主设计、研发、生产、服务能力，是行业内产业链条最完整的企业之一。已研发量产芯片 40 余款、天线阵面 60 余款，形成毫米波芯片（硅基 CMOS 相控阵芯片，覆盖 X 至 D 波段的每一个典型频段）、相控阵天线（全球首台 Ka 卫通平板相控阵天线，国内首条平板相控阵天线生产线，国际唯二年产能力超万套企业）、相控阵测试系统（紧缩场、CNAS 民用相控阵测试专用实验室）三大产品线，实现从 X 到 D 波段全覆盖。其相控阵宽带卫星通信技术曾为神舟十三号返回提供通信保障，是全球首次在航天员返回通信保障中应用相控阵宽带卫星通信技术。下设南京汇君半导体、赫兹（成都）检测、天锐智造（成都）、天锐星通（上海）四家全资子公司。截至 2026-10，已获授权发明专利 151 项、国际专利 8 项、集成电路布图 15 项；2023 年荣获国家技术发明二等奖。","round":"F 轮","lastFunding":"2025-06","latestFunding":"2025-06 · F 轮（投资方：浦东创投集团）","latestTech":"Q/V、W 频段硅基 CMOS 相控阵芯片及平板相控阵天线产品，填补国内 W 频段相控阵芯片及天线产品空白；相控阵芯片及天线产品实现从 X 到 D 波段每一个典型频段的全覆盖","tech":[{"date":"2025-06","title":"完成 F 轮融资，浦东创投集团投资"},{"date":"2023-06","title":"推出 Q/V、W 频段硅基 CMOS 相控阵芯片及平板相控阵天线产品，填补国内 W 频段空白"},{"date":"2023","title":"荣获国家技术发明二等奖"},{"date":"2021-10","title":"相控阵终端为神舟十三号返回提供通信保障，全球首次在航天员返回通信保障中应用相控阵宽带卫星通信技术"}],"funding":[{"date":"2025-06","round":"F 轮","inv":"浦东创投集团"},{"date":"2023-09","round":"E+ 轮","inv":"德诺资本、全矽创投"},{"date":"2023-05","round":"E 轮","inv":"国新融智、沅灏基金"},{"date":"2022-06","round":"D 轮","inv":"中新融创、和合资本、武岳峰科创、中启基金、川航方富、东方华盖"},{"date":"2021-01","round":"C 轮","inv":"盈富泰克、珞珈方圆"},{"date":"2020-10","round":"B 轮","inv":"中航国际、方广资本"},{"date":"2020-07","round":"A 轮","inv":"前海基础投资"}],"investorsStructured":[{"name":"武岳峰科创","role":"follow","round":"D 轮","date":"2022-06","kind":"vc"},{"name":"中新融创","role":"lead","round":"D 轮","date":"2022-06","kind":"vc"},{"name":"中航国际","role":"lead","round":"B 轮","date":"2020-10","kind":"gov"},{"name":"方广资本","role":"follow","round":"B 轮","date":"2020-10","kind":"vc"},{"name":"盈富泰克","role":"lead","round":"C 轮","date":"2021-01","kind":"gov"},{"name":"国新融智","role":"lead","round":"E 轮","date":"2023-05","kind":"gov"},{"name":"德诺资本","role":"lead","round":"E+ 轮","date":"2023-09","kind":"vc"},{"name":"浦东创投集团","role":"lead","round":"F 轮","date":"2025-06","kind":"gov"}],"executives":[{"name":"张成军","title":"法定代表人","role":"management"},{"name":"赵涤燹","title":"董事","role":"board","bio":"持股 12.29%"},{"name":"王凯","title":"董事","role":"board","bio":"持股 13.60%"}],"note":"核心团队在毫米波相控阵领域开创多项国内首创；已布局芯片设计、芯片封装、相控阵天线组件和毫米波测试系统开发。"}'::jsonb, '2026-10-15T00:33:47.513Z'),
('安澜万锦', NULL, 'semiconductor', 'material', false, '战略融资', NULL, 34.53, NULL, '2025-11', '{"name":"安澜万锦","industry":"semiconductor","seg":"material","listed":false,"desc":"江苏安澜万锦电子股份有限公司（1993-07 成立，原常州通达万锦电子，法定代表人梁建锋）是国家级专精特新「小巨人」企业，专注数据通信用高速电子线材及特种线材的研发、生产与销售，主要服务数据中心高速互连、消费电子精密连接等场景，构建「高速铜缆 + 特种线材 + 电声元件」三位一体产品矩阵，并战略性拓展光连接业务。公司单通道 112Gbps、224Gbps 高速铜缆已规模化量产（224Gbps 为当前行业量产最高速率等级），448Gbps 产品已完成送样测试，是国内首批成功研发 PCIe5.0 高速铜缆、国内最早量产 112Gbps/224Gbps 高速铜缆的企业之一。海外核心客户覆盖安费诺、莫仕、泰科等全球头部铜连接厂商，国内主要客户包括庆虹电子、华丰科技等高速连接器及线缆组件骨干企业，产品终端应用于英伟达、华为、谷歌等算力厂商及苹果、三星等消费品牌。2023-2025 年营收分别为 2.84 亿、5.24 亿、12.99 亿元，2025 年高速通信线缆收入占比达 77.43%（9.97 亿元），全球高速铜缆市占率 2024/2025 年分别为 4.19%/8.42%。2026-06 上交所主板 IPO 获受理，拟募资 12 亿元。","valuation":34.53,"round":"战略融资","lastFunding":"2025-11","latestFunding":"2025-11 · 递表前最后一轮（14 家机构，腾讯投资 / 武岳峰创投 / 云启资本 / 光合创投等，合计增资 4.53 亿元，估值推高至 34.53 亿元）","latestTech":"单通道 112Gbps、224Gbps 高速铜缆规模化量产（224Gbps 为行业量产最高速率等级），448Gbps 产品完成送样测试；成为国内最早量产 112Gbps/224Gbps 高速铜缆的企业之一","tech":[{"date":"2026-06","title":"上交所主板 IPO 获受理（保荐机构东方证券），拟发行不低于 4224 万股、募资 12 亿元"},{"date":"2025-11","title":"递表前最后一轮融资，14 家机构涌入增资 4.53 亿元，估值推高至 34.53 亿元"}],"funding":[{"date":"2025-11","round":"战略融资","amount":"4.53 亿元","inv":"腾讯投资、富土基金、云启资本、光合创投、武岳峰创投、司桐资本、冠亚投资、方道资本等 14 家机构"},{"date":"2025-04","round":"增资","amount":"3656 万元","inv":"慈溪亿群、珠海恒辉、宋益群、何洪（16.33 元/股，对应估值 12.65 亿元）"},{"date":"2024-12","round":"增资","amount":"2800 万元","inv":"共青城、海南掌科（16.33 元/股）"}],"investorsStructured":[{"name":"武岳峰创投","role":"follow","round":"战略融资","date":"2025-11","kind":"vc","note":"常州武岳峰仟朗二期半导体产业投资基金持股 2.47%"},{"name":"腾讯投资","role":"follow","round":"战略融资","date":"2025-11","kind":"cvc","note":"广西腾讯创业投资持股 4.35%"},{"name":"云启资本","role":"follow","round":"战略融资","date":"2025-11","kind":"vc"},{"name":"光合创投","role":"follow","round":"战略融资","date":"2025-11","kind":"vc"}],"executives":[{"name":"梁建锋","title":"董事长、法定代表人","role":"management","bio":"直接持股 10.1%，与配偶刘言合计控制 76.64% 表决权"},{"name":"刘言","title":"实际控制人之一","role":"board","bio":"直接持股 11.99%，通过上丰投资持股 47.81%"}],"note":"2023-2025 年前五大客户收入占比 75.75%/80.74%/86.81%，客户集中度偏高；境内主要客户为庆虹电子、华丰科技。"}'::jsonb, '2026-10-15T00:33:47.513Z')
